{"implementation":"def solve(case):
    segments = case["segments"]
    budget = case["budget"]
    n = len(segments)
    allocations = [min(int(s["minimum"]), int(s["capacity"])) for s in segments]
    minimum_total = sum(allocations)

    if budget < minimum_total:
        allocations = [0] * n
        remaining = budget
        for i, segment in enumerate(segments):
            amount = min(remaining, min(int(segment["minimum"]), int(segment["capacity"])))
            allocations[i] = amount
            remaining -= amount
            if remaining <= 0:
                break
    else:
        remaining = budget - minimum_total
        while remaining > 0:
            eligible = [i for i, segment in enumerate(segments) if allocations[i] < int(segment["capacity"])]
            if not eligible:
                break
            weight_total = sum(max(0, int(segments[i]["importance"])) for i in eligible)
            if weight_total <= 0:
                for i in eligible:
                    if remaining <= 0:
                        break
                    allocations[i] += 1
                    remaining -= 1
                continue
            grants = [0] * n
            used = 0
            remainders = []
            for i in eligible:
                room = int(segments[i]["capacity"]) - allocations[i]
                numerator = remaining * max(0, int(segments[i]["importance"]))
                grant = min(room, numerator // weight_total)
                grants[i] = grant
                used += grant
                remainders.append((numerator % weight_total, -i, i))
            if used:
                for i in eligible:
                    allocations[i] += grants[i]
                remaining -= used
                continue
            remainders.sort(reverse=True)
            allocated = False
            for _, _, i in remainders:
                if allocations[i] < int(segments[i]["capacity"]):
                    allocations[i] += 1
                    remaining -= 1
                    allocated = True
                    break
            if not allocated:
                break

    by_name = {segment["name"]: allocations[i] for i, segment in enumerate(segments)}
    return {"allocations": allocations, "by_name": by_name, "total": sum(allocations)}
"}
